  1	#!/usr/bin/env perl
  2	use strict;
  3	use warnings;
  4	use IO::Uncompress::Gunzip qw($GunzipError);
  5	use JSON::PP qw(encode_json);
  6	
  7	die "usage: validate_trimmed_pairs.pl raw_forward raw_reverse out_forward out_reverse\n"
  8	    unless @ARGV == 4;
  9	my ($raw_f, $raw_r, $out_f, $out_r) = @ARGV;
 10	
 11	sub open_gz {
 12	    my ($path) = @_;
 13	    my $fh = IO::Uncompress::Gunzip->new($path)
 14	        or die "cannot open $path as gzip: $GunzipError\n";
 15	    return $fh;
 16	}
 17	
 18	sub next_record {
 19	    my ($fh, $path) = @_;
 20	    my $h = <$fh>;
 21	    return undef unless defined $h;
 22	    my $s = <$fh>;
 23	    my $p = <$fh>;
 24	    my $q = <$fh>;
 25	    die "truncated FASTQ record in $path\n" unless defined $s && defined $p && defined $q;
 26	    chomp($h); chomp($s); chomp($p); chomp($q);
 27	    die "invalid FASTQ record in $path\n" unless $h =~ /^@/ && $p eq '+';
 28	    return [$h, $s, $q];
 29	}
 30	
 31	sub core_id {
 32	    my ($h) = @_;
 33	    $h =~ s/^@//;
 34	    my ($id) = split(/\s+/, $h, 2);
 35	    $id =~ s{/[12]$}{};
 36	    return $id;
 37	}
 38	
 39	sub read_metrics {
 40	    my ($rec) = @_;
 41	    my ($seq, $qual) = ($rec->[1], $rec->[2]);
 42	    die "sequence/quality length mismatch for " . $rec->[0] . "\n"
 43	        unless length($seq) == length($qual);
 44	    my ($low, $n) = (0, 0);
 45	    for (my $i = 0; $i < length($seq); ++$i) {
 46	        ++$low if ord(substr($qual, $i, 1)) - 33 < 20;
 47	        ++$n if substr($seq, $i, 1) =~ /N/i;
 48	    }
 49	    return {length => length($seq), low => $low, n => $n};
 50	}
 51	
 52	sub add_mate_metrics {
 53	    my ($summary, $which, $m) = @_;
 54	    ++$summary->{"${which}_reads"};
 55	    $summary->{"${which}_min_length"} = $m->{length}
 56	        if !defined($summary->{"${which}_min_length"}) || $m->{length} < $summary->{"${which}_min_length"};
 57	    $summary->{"${which}_max_length"} = $m->{length}
 58	        if !defined($summary->{"${which}_max_length"}) || $m->{length} > $summary->{"${which}_max_length"};
 59	    $summary->{"${which}_max_n"} = $m->{n}
 60	        if $m->{n} > $summary->{"${which}_max_n"};
 61	    $summary->{"${which}_max_low_bases"} = $m->{low}
 62	        if $m->{low} > $summary->{"${which}_max_low_bases"};
 63	    ++$summary->{"${which}_filter_violations"}
 64	        if $m->{length} < 15 || $m->{n} > 5 || $m->{low} * 100 > $m->{length} * 40;
 65	}
 66	
 67	my @raw_fh = (open_gz($raw_f), open_gz($raw_r));
 68	my @out_fh = (open_gz($out_f), open_gz($out_r));
 69	my $next_out_f = next_record($out_fh[0], $out_f);
 70	my $next_out_r = next_record($out_fh[1], $out_r);
 71	my %s = (
 72	    raw_pairs => 0,
 73	    output_pairs => 0,
 74	    raw_id_mismatches => 0,
 75	    output_id_mismatches => 0,
 76	    prefix_violations => 0,
 77	    forward_reads => 0,
 78	    reverse_reads => 0,
 79	    forward_filter_violations => 0,
 80	    reverse_filter_violations => 0,
 81	    forward_max_n => 0,
 82	    reverse_max_n => 0,
 83	    forward_max_low_bases => 0,
 84	    reverse_max_low_bases => 0,
 85	);
 86	
 87	while (1) {
 88	    my $rf = next_record($raw_fh[0], $raw_f);
 89	    my $rr = next_record($raw_fh[1], $raw_r);
 90	    die "raw mates have different record counts near raw pair " . ($s{raw_pairs} + 1) . "\n"
 91	        if defined($rf) != defined($rr);
 92	    last unless defined $rf;
 93	    ++$s{raw_pairs};
 94	    ++$s{raw_id_mismatches} if core_id($rf->[0]) ne core_id($rr->[0]);
 95	
 96	    if (defined $next_out_f || defined $next_out_r) {
 97	        die "output mates have different record counts near output pair " . ($s{output_pairs} + 1) . "\n"
 98	            if defined($next_out_f) != defined($next_out_r);
 99	        my $raw_id = core_id($rf->[0]);
100	        my $out_id = core_id($next_out_f->[0]);
101	        if ($raw_id eq $out_id) {
102	            ++$s{output_pairs};
103	            ++$s{output_id_mismatches} if core_id($next_out_f->[0]) ne core_id($next_out_r->[0]);
104	            my $mf = read_metrics($next_out_f);
105	            my $mr = read_metrics($next_out_r);
106	            add_mate_metrics(\%s, 'forward', $mf);
107	            add_mate_metrics(\%s, 'reverse', $mr);
108	            ++$s{prefix_violations}
109	                unless index($rf->[1], $next_out_f->[1]) == 0
110	                    && index($rf->[2], $next_out_f->[2]) == 0
111	                    && index($rr->[1], $next_out_r->[1]) == 0
112	                    && index($rr->[2], $next_out_r->[2]) == 0;
113	            $next_out_f = next_record($out_fh[0], $out_f);
114	            $next_out_r = next_record($out_fh[1], $out_r);
115	        }
116	    }
117	}
118	
119	die "output has a record not present in raw inputs\n" if defined($next_out_f) || defined($next_out_r);
120	$s{ids_synchronized} = ($s{raw_id_mismatches} == 0 && $s{output_id_mismatches} == 0) ? JSON::PP::true : JSON::PP::false;
121	$s{prefix_only_changes} = ($s{prefix_violations} == 0) ? JSON::PP::true : JSON::PP::false;
122	$s{all_output_pairs_pass_filters} = ($s{forward_filter_violations} == 0 && $s{reverse_filter_violations} == 0) ? JSON::PP::true : JSON::PP::false;
123	print encode_json(\%s), "\n";

